package org.eclipse.rdf4j.tools.serverboot;

import static org.assertj.core.api.Assertions.assertThat;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Path;
import java.util.Map;

import org.eclipse.rdf4j.common.platform.Platform;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.web.server.servlet.context.ServletWebServerApplicationContext;
import org.springframework.context.ConfigurableApplicationContext;

class WorkbenchSessionCookieOptionsTest {

	@ParameterizedTest
	@ValueSource(strings = { "omitted", "none" })
	void supportedCookieOptionsStartAndPreserveWirePolicy(String policy, @TempDir Path dataDir) throws Exception {
		String previous = System.getProperty(Platform.APPDATA_BASEDIR_PROPERTY);
		System.setProperty(Platform.APPDATA_BASEDIR_PROPERTY, dataDir.toString());
		SpringApplication application = new SpringApplication(Rdf4jServerWorkbenchApplication.class);
		application.setDefaultProperties(Map.of("server.port", "0", "server.servlet.session.cookie.same-site", policy,
				"server.servlet.session.cookie.secure", "true", "server.servlet.session.cookie.http-only", "true"));
		try (ConfigurableApplicationContext context = application.run();
				HttpClient client = HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NORMAL).build()) {
			int port = ((ServletWebServerApplicationContext) context).getWebServer().getPort();
			URI uri = URI.create("http://localhost:" + port + "/rdf4j-workbench/repositories");
			HttpResponse<String> response = client.send(HttpRequest.newBuilder(uri).build(),
					HttpResponse.BodyHandlers.ofString());
			assertThat(response.statusCode()).isEqualTo(200);
			assertThat(response.headers().allValues("Set-Cookie")).anySatisfy(cookie -> {
				assertThat(cookie).startsWith("JSESSIONID=").contains("Secure", "HttpOnly", "Path=/");
				if (policy.equals("omitted")) {
					assertThat(cookie).doesNotContain("SameSite");
				} else {
					assertThat(cookie).contains("SameSite=None");
				}
			});
		} finally {
			if (previous == null) {
				System.clearProperty(Platform.APPDATA_BASEDIR_PROPERTY);
			} else {
				System.setProperty(Platform.APPDATA_BASEDIR_PROPERTY, previous);
			}
		}
	}
}
